-- Classic-era quest and NPC data from CMaNGOS classic-db.
--
-- The tables live in the load-on-demand addon ForeverPath_ClassicDB
-- (generated by tools/ClassicDbExtract), which writes them into
-- ForeverPath.ClassicData:
--   quests[id]  = { title, level, minLevel, side, classMask, zoneOrSort,
--                   starterNpcs, starterObjects, starterItem, enderNpcs,
--                   enderObjects, items, kills, choiceRewards, rewards,
--                   reputation, prerequisites, followUp, providedItem,
--                   objectives, groupSize, skill, breadcrumbFor, type }
--   npcs[id]    = { name, subName, minLevel, maxLevel, npcFlags, spawns }
--   objects[id] = { name, type, spawns }
--   spawns      = { uiMapID, x, y, ... } with x, y in 0.1% of the zone map;
--                 a negative uiMapID is an instance (-mapID).
--   zones[uiMapID], instances[mapID] = names
--
-- This is the baseline under everything Forever-specific: quest facts
-- learned in game, the shipped quest catalogue and the ForeverDungeonJournal
-- / Attune bridges all take precedence (see QuestProvider). Entries carry
-- source = "classic" so the UI can say where a fact came from.
local _, ns = ...

local Compat = ns.Compat
local Log = ns.Log

local ClassicDB = { entries = {}, loadTried = false }
ns.ClassicDB = ClassicDB

ClassicDB.ADDON = "ForeverPath_ClassicDB"
ClassicDB.ALLIANCE, ClassicDB.HORDE = 1, 2
ClassicDB.CHAIN_LIMIT = 40

local function data()
  local d = ns.ClassicData
  if type(d) == "table" and type(d.quests) == "table" then return d end
  return nil
end

-- Loads the data addon once (it is load-on-demand). True when the data is there.
function ClassicDB.Load()
  if data() then return true end
  if not ClassicDB.loadTried then
    ClassicDB.loadTried = true
    if Compat.LoadAddOn then
      local ok, loaded, reason = pcall(Compat.LoadAddOn, ClassicDB.ADDON)
      if not ok or not loaded then
        ClassicDB.loadError = ok and tostring(reason or "not loaded") or tostring(loaded)
        Log.Debug("%s not loaded: %s", ClassicDB.ADDON, ClassicDB.loadError)
      end
    else
      ClassicDB.loadError = "this client cannot load addons on demand"
    end
  end
  return data() ~= nil
end

function ClassicDB.IsAvailable()
  return data() ~= nil
end

-- Forgets derived indexes (after the data changes, and in tests).
function ClassicDB.Reset()
  ClassicDB.entries = {}
  ClassicDB.rewardIndex = nil
  ClassicDB.reputationIndex = nil
  ClassicDB.titleIndex = nil
end

---------------------------------------------------------------------------
-- Player context
---------------------------------------------------------------------------
function ClassicDB.PlayerSide()
  if type(UnitFactionGroup) == "function" then
    local ok, faction = pcall(UnitFactionGroup, "player")
    if ok and faction == "Alliance" then return ClassicDB.ALLIANCE end
    if ok and faction == "Horde" then return ClassicDB.HORDE end
  end
  return nil
end

function ClassicDB.PlayerClassID()
  if type(UnitClass) == "function" then
    local ok, _, _, classID = pcall(UnitClass, "player")
    if ok and tonumber(classID) then return tonumber(classID) end
  end
  return nil
end

local function hasClassBit(mask, classID)
  if not mask or mask == 0 or not classID then return true end
  return math.floor(mask / 2 ^ (classID - 1)) % 2 == 1
end

-- Can this character take the quest (faction and class)?
function ClassicDB.Eligible(questID, side, classID)
  local row = data() and data().quests[questID]
  if not row then return false end
  side = side or ClassicDB.PlayerSide()
  classID = classID or ClassicDB.PlayerClassID()
  local questSide = row[4] or 0
  if questSide ~= 0 and side and questSide ~= side then return false end
  return hasClassBit(row[5], classID)
end

---------------------------------------------------------------------------
-- Places
---------------------------------------------------------------------------
function ClassicDB.ZoneName(uiMapID)
  local d = data()
  uiMapID = tonumber(uiMapID)
  if not uiMapID then return nil end
  if uiMapID < 0 then
    return d and d.instances and d.instances[-uiMapID] or nil
  end
  local name = d and d.zones and d.zones[uiMapID]
  if name then return name end
  local map = _G.C_Map
  if type(map) == "table" and type(map.GetMapInfo) == "function" then
    local ok, info = pcall(map.GetMapInfo, uiMapID)
    if ok and type(info) == "table" then return info.name end
  end
  return nil
end

-- { { uiMapID, x, y, zone, instance } } with x, y as 0-1 fractions (nil inside instances).
function ClassicDB.Spawns(flat)
  local out = {}
  if type(flat) ~= "table" then return out end
  for i = 1, #flat, 3 do
    local ui = flat[i]
    if ui then
      if ui < 0 then
        out[#out + 1] = { uiMapID = ui, zone = ClassicDB.ZoneName(ui), instance = true }
      else
        out[#out + 1] = { uiMapID = ui, x = (flat[i + 1] or 0) / 1000, y = (flat[i + 2] or 0) / 1000, zone = ClassicDB.ZoneName(ui) }
      end
    end
  end
  return out
end

function ClassicDB.Npc(npcID)
  local d = data()
  local row = d and d.npcs[tonumber(npcID) or 0]
  if not row then return nil end
  return { id = tonumber(npcID), name = row[1], subName = row[2], minLevel = row[3], maxLevel = row[4], npcFlags = row[5], spawns = ClassicDB.Spawns(row[6]) }
end

function ClassicDB.Object(objectID)
  local d = data()
  local row = d and d.objects and d.objects[tonumber(objectID) or 0]
  if not row then return nil end
  return { id = tonumber(objectID), name = row[1], type = row[2], spawns = ClassicDB.Spawns(row[3]) }
end

-- A place for the first NPC (or object) in the list that has one:
-- { name, mapID, x, y, zone, label, classic = true }. Zone-map spawns win
-- over instance spawns.
function ClassicDB.PlaceOf(npcIDs, objectIDs)
  local function from(thing)
    if not thing then return nil end
    local best
    for _, spawn in ipairs(thing.spawns) do
      if not spawn.instance then best = spawn break end
      best = best or spawn
    end
    local place = { name = thing.name, classic = true }
    if best then
      place.zone = best.zone
      if not best.instance then place.mapID, place.x, place.y = best.uiMapID, best.x, best.y end
    end
    place.label = place.name .. (place.zone and (" - " .. place.zone) or "")
    return place
  end
  for _, id in ipairs(npcIDs or {}) do
    local place = from(ClassicDB.Npc(id))
    if place then return place end
  end
  for _, id in ipairs(objectIDs or {}) do
    local place = from(ClassicDB.Object(id))
    if place then return place end
  end
  return nil
end

---------------------------------------------------------------------------
-- Quests
---------------------------------------------------------------------------
local SIDE_NAMES = { [0] = "Both", [1] = "Alliance", [2] = "Horde" }

local function pairList(flat, fields)
  local out = {}
  if type(flat) ~= "table" then return out end
  for i = 1, #flat, 2 do
    local entry = {}
    entry[fields[1]] = flat[i]
    entry[fields[2]] = flat[i + 1] or 1
    out[#out + 1] = entry
  end
  return out
end

-- A quest in QuestProvider's entry shape (cached), or nil.
function ClassicDB.Quest(questID)
  questID = tonumber(questID)
  local d = data()
  local row = questID and d and d.quests[questID]
  if not row then return nil end
  local cached = ClassicDB.entries[questID]
  if cached then return cached end
  local rewards, choice = {}, false
  for _, r in ipairs(pairList(row[15], { "itemID", "count" })) do
    r.fixed = true
    rewards[#rewards + 1] = r
  end
  for _, r in ipairs(pairList(row[14], { "itemID", "count" })) do
    rewards[#rewards + 1] = r
    choice = true
  end
  local giver = ClassicDB.PlaceOf(row[7], row[8])
  local entry = {
    id = questID, name = row[1], level = row[2] ~= 0 and row[2] or nil, requires = row[3] ~= 0 and row[3] or nil,
    faction = SIDE_NAMES[row[4] or 0] or "Both", classMask = row[5] or 0,
    instance = (giver and giver.zone) or "Classic quests", location = giver and giver.zone or nil,
    objective = row[20], rewards = rewards, rewardChoice = choice,
    source = "classic", classic = true,
    prerequisites = row[17], followUp = row[18], providedItem = row[19],
    starterNpcs = row[7], starterObjects = row[8], starterItem = row[9], enderNpcs = row[10], enderObjects = row[11],
    items = pairList(row[12], { "itemID", "count" }), kills = pairList(row[13], { "id", "count" }),
    reputation = pairList(row[16], { "factionID", "value" }),
    groupSize = row[21], skill = row[22], breadcrumbFor = row[23], questType = row[24],
  }
  ClassicDB.entries[questID] = entry
  return entry
end

function ClassicDB.Giver(questID)
  local entry = ClassicDB.Quest(questID)
  if not entry then return nil end
  local place = ClassicDB.PlaceOf(entry.starterNpcs, entry.starterObjects)
  if not place and entry.starterItem and ns.ItemProvider then
    local name = ns.ItemProvider.GetName(entry.starterItem)
    place = { name = name, label = name .. " (item)", item = entry.starterItem, classic = true }
  end
  return place
end

function ClassicDB.Turnin(questID)
  local entry = ClassicDB.Quest(questID)
  if not entry then return nil end
  return ClassicDB.PlaceOf(entry.enderNpcs, entry.enderObjects)
end

-- The items a quest asks for: { { itemID, count } }.
function ClassicDB.RequiredItems(questID)
  local entry = ClassicDB.Quest(questID)
  return entry and entry.items or {}
end

local function buildIndexes()
  local d = data()
  local rewards, reputation, titles = {}, {}, {}
  if d then
    for questID, row in pairs(d.quests) do
      for _, field in ipairs({ 14, 15 }) do
        local list = row[field]
        if type(list) == "table" then
          for i = 1, #list, 2 do
            local itemID = list[i]
            rewards[itemID] = rewards[itemID] or {}
            table.insert(rewards[itemID], questID)
          end
        end
      end
      if type(row[16]) == "table" then
        for i = 1, #row[16], 2 do
          local factionID, value = row[16][i], row[16][i + 1]
          if value and value > 0 then
            reputation[factionID] = reputation[factionID] or {}
            table.insert(reputation[factionID], { questID = questID, amount = value })
          end
        end
      end
      titles[#titles + 1] = { questID = questID, lower = string.lower(row[1] or "") }
    end
    for _, list in pairs(rewards) do table.sort(list) end
    for _, list in pairs(reputation) do
      table.sort(list, function(a, b)
        if a.amount ~= b.amount then return a.amount > b.amount end
        return a.questID < b.questID
      end)
    end
  end
  ClassicDB.rewardIndex, ClassicDB.reputationIndex, ClassicDB.titleIndex = rewards, reputation, titles
end

-- Quests this character can take that reward itemID (entries).
function ClassicDB.QuestsRewarding(itemID, side, classID)
  if not data() then return {} end
  if not ClassicDB.rewardIndex then buildIndexes() end
  local out = {}
  for _, questID in ipairs(ClassicDB.rewardIndex[tonumber(itemID) or 0] or {}) do
    if ClassicDB.Eligible(questID, side, classID) then out[#out + 1] = ClassicDB.Quest(questID) end
  end
  return out
end

-- Quests this character can take that give reputation with factionID:
-- { { questID, amount, entry } }, largest first.
function ClassicDB.ReputationQuests(factionID, side, classID)
  if not data() then return {} end
  if not ClassicDB.reputationIndex then buildIndexes() end
  local out = {}
  for _, source in ipairs(ClassicDB.reputationIndex[tonumber(factionID) or 0] or {}) do
    if ClassicDB.Eligible(source.questID, side, classID) then
      out[#out + 1] = { questID = source.questID, amount = source.amount, entry = ClassicDB.Quest(source.questID) }
    end
  end
  return out
end

-- Quest ids whose title contains needle (lowercase), eligible for this character.
function ClassicDB.Search(needle, side, classID)
  if not data() then return {} end
  if not ClassicDB.titleIndex then buildIndexes() end
  local out = {}
  for _, t in ipairs(ClassicDB.titleIndex) do
    if string.find(t.lower, needle, 1, true) and ClassicDB.Eligible(t.questID, side, classID) then
      out[#out + 1] = t.questID
    end
  end
  return out
end

-- The quests to do before questID, then questID, in order. For an "any of"
-- prerequisite group the member already completed is taken, else the first
-- this character can take. isCompleted(questID) -> bool.
function ClassicDB.ChainTo(questID, isCompleted, side, classID)
  local order, seen, follows = {}, {}, {}
  local depth = 0
  local function visit(id)
    if seen[id] or depth > ClassicDB.CHAIN_LIMIT then return end
    seen[id] = true
    depth = depth + 1
    local entry = ClassicDB.Quest(id)
    follows[id] = {}
    for _, group in ipairs(entry and entry.prerequisites or {}) do
      local pick
      for _, member in ipairs(group) do
        if isCompleted and isCompleted(member) then pick = member break end
      end
      if not pick then
        for _, member in ipairs(group) do
          if ClassicDB.Eligible(member, side, classID) then pick = member break end
        end
      end
      pick = pick or group[1]
      if pick and ClassicDB.Quest(pick) then
        visit(pick)
        table.insert(follows[id], pick)
      end
    end
    order[#order + 1] = id
  end
  visit(tonumber(questID))
  return order, follows
end

function ClassicDB.Counts()
  local d = data()
  local function count(t)
    local n = 0
    for _ in pairs(t or {}) do n = n + 1 end
    return n
  end
  return d and count(d.quests) or 0, d and count(d.npcs) or 0, d and count(d.objects) or 0
end

function ClassicDB.Status()
  if not data() then
    return string.format("Classic data: %s is not loaded (%s); classic-era quests, givers and spawns are unavailable.", ClassicDB.ADDON, ClassicDB.loadError or "not installed")
  end
  local quests, npcs, objects = ClassicDB.Counts()
  local meta = data().meta or {}
  return string.format("Classic data: %d quests, %d NPCs, %d objects from %s %s.", quests, npcs, objects, meta.source or "CMaNGOS classic-db", string.sub(tostring(meta.commit or "?"), 1, 8))
end

function ClassicDB.Init()
  local loaded = ClassicDB.Load()
  ClassicDB.Reset()
  Log.Debug("%s", ClassicDB.Status())
  return loaded
end
